css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .82); position: relative; }
.loader .wheel { position: absolute; bottom: 6%; left: 6%; width: 88%; height: 20%; border-radius: 50%; overflow: hidden; background: var(--accent); }
.loader .wheel::after { content: ''; position: absolute; left: -30%; top: -140%; width: 160%; height: 380%; background: conic-gradient(from 0deg, var(--accent-2), var(--accent) 40%, var(--accent-2) 70%, var(--accent)); animation: clay-wheel calc(var(--loader-speed) * 1.1) linear infinite; }
.loader .clay { position: absolute; bottom: 16%; left: 30%; width: 40%; height: 54%; background: linear-gradient(var(--accent-2), var(--accent)); border-radius: 40% 40% 22% 22% / 30% 30% 18% 18%; animation: clay-shape calc(var(--loader-speed) * 2.8) ease-in-out infinite; }
.loader .clay::after { content: ''; position: absolute; left: 20%; right: 20%; top: 7%; height: 13%; border-radius: 50%; background: color-mix(in srgb, #000 26%, transparent); }
@keyframes clay-wheel { to { transform: rotate(1turn); } }
@keyframes clay-shape { 0%, 100% { width: 40%; height: 54%; left: 30%; border-radius: 40% 40% 22% 22% / 30% 30% 18% 18%; } 34% { width: 30%; height: 66%; left: 35%; border-radius: 52% 52% 20% 20% / 42% 42% 15% 15%; } 66% { width: 52%; height: 42%; left: 24%; border-radius: 32% 32% 26% 26% / 26% 26% 20% 20%; } }
